var list_projects_default = defineTool({
  name: "list_projects",
  title: "List projects",
  description: "List all works by QinLong & ChenJie studio (animations, video essays, short films, commercials). Optionally filter by year or type.",
  inputSchema: {
    year: z.string().optional().describe("Filter by year, e.g. '2023' or '2023-2024'."),
    type: z.string().optional().describe("Filter by type, e.g. 'Short Film', 'Video essay', 'Commercial', 'Independent Animation'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ year, type }) => {
    const items = mcpProjects.filter(
      (p) => (!year || p.year.toLowerCase().includes(year.toLowerCase())) && (!type || p.type.toLowerCase().includes(type.toLowerCase()))
    );
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { projects: items, count: items.length }
    };
  }
});

// src/lib/mcp/tools/get-project.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z as z2 } from "npm:zod@^4.4.3";
var get_project_default = defineTool2({
  name: "get_project",
  title: "Get project",
  description: "Get full details for a single project by its id. Use list_projects first to discover valid ids.",
  inputSchema: {
    id: z2.string().min(1).describe("The project id, e.g. 'between-us' or 'entering-cloud'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id }) => {
    const project = mcpProjects.find((p) => p.id === id);
    if (!project) {
      return {
        content: [{ type: "text", text: `No project found with id '${id}'.` }],
        isError: true
      };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(project, null, 2) }],
      structuredContent: { project }
    };
  }
});

